"use client";

import React, { useState, useMemo } from "react";
import PageHeader from "@/components/common/PageHeader";
import { 
  Calendar as CalendarIcon, 
  Info, 
  UserCheck,
  Users,
  PieChart,
  ArrowRight,
  AlertCircle
} from "lucide-react";

const LEAVE_BALANCES = { annual: 22, sick: 10, casual: 7 };

export default function RequestAbsencePage() {
  const [selectedRange, setSelectedRange] = useState<{ start: string; end: string }>({ start: "", end: "" });
  const [leaveType, setLeaveType] = useState("annual");

  // --- 1. FIXED WEEKEND LOGIC ---
  // We use the native getDay() where 0=Sun, 6=Sat
  const analysis = useMemo(() => {
    if (!selectedRange.start || !selectedRange.end) return { working: 0, weekend: 0 };
    let working = 0;
    let weekend = 0;
    let cur = new Date(selectedRange.start);
    let end = new Date(selectedRange.end);

    while (cur <= end) {
      const day = cur.getDay(); 
      if (day === 0 || day === 6) weekend++;
      else working++;
      cur.setDate(cur.getDate() + 1);
    }
    return { working, weekend };
  }, [selectedRange]);

  const handleDateClick = (dateStr: string) => {
    if (!selectedRange.start || (selectedRange.start && selectedRange.end)) {
      setSelectedRange({ start: dateStr, end: "" });
    } else {
      const start = new Date(selectedRange.start);
      const clicked = new Date(dateStr);
      if (clicked < start) setSelectedRange({ start: dateStr, end: "" });
      else setSelectedRange({ ...selectedRange, end: dateStr });
    }
  };

  return (
    <div className="mx-auto max-w-7xl px-4 py-8">
      <PageHeader
        title="Request Absence"
        subtitle="Intelligent leave management with team capacity awareness."
        breadcrumbs={[{ label: "Time Management" }, { label: "Request Absence" }]}
      />

      <div className="mt-8 grid grid-cols-1 gap-8 lg:grid-cols-12">
        
        {/* LEFT: Balance & Team Planning Sidebar */}
        <div className="lg:col-span-3 space-y-6 order-2 lg:order-1">
          {/* Real-time Balance Card */}
          <div className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm dark:border-gray-800 dark:bg-white/[0.03]">
            <h3 className="flex items-center gap-2 text-sm font-bold text-gray-400 uppercase tracking-wider">
              <PieChart className="h-4 w-4" /> Current Balance
            </h3>
            <div className="mt-4 space-y-4">
               <BalanceRow label="Annual" current={LEAVE_BALANCES.annual} requested={analysis.working} color="bg-blue-600" />
               <BalanceRow label="Sick" current={LEAVE_BALANCES.sick} requested={0} color="bg-rose-500" />
            </div>
          </div>

          {/* Team Capacity Awareness */}
          <div className="rounded-2xl border border-gray-200 bg-slate-900 p-5 text-white">
            <h3 className="flex items-center gap-2 text-xs font-bold uppercase tracking-widest text-slate-400">
              <Users className="h-4 w-4" /> Team Capacity
            </h3>
            <p className="mt-3 text-xs text-slate-400">Predicted team bandwidth during your selected dates:</p>
            <div className="mt-4 flex items-end gap-1 h-12">
                {[40, 70, 90, 85, 30, 60, 80].map((v, i) => (
                    <div key={i} style={{ height: `${v}%` }} className={`flex-1 rounded-t-sm ${v < 40 ? 'bg-rose-500' : 'bg-blue-500/40'}`} />
                ))}
            </div>
            {analysis.working > 3 && (
                <div className="mt-4 flex gap-2 rounded-lg bg-white/5 p-2 text-[10px] text-amber-400">
                    <AlertCircle className="h-3 w-3 shrink-0" />
                    <span>Heavy overlap with Engineering Sprints detected.</span>
                </div>
            )}
          </div>
        </div>

        {/* CENTER: Calendar Engine */}
        <div className="lg:col-span-6 order-1 lg:order-2">
          <div className="rounded-3xl border border-gray-200 bg-white p-8 shadow-sm dark:border-gray-800 dark:bg-white/[0.03]">
            <div className="mb-6 flex items-center justify-between">
              <h2 className="text-xl font-bold italic">January 2026</h2>
              <div className="flex gap-4 text-[10px] font-bold uppercase text-gray-400">
                <span className="flex items-center gap-1"><span className="h-2 w-2 rounded-full bg-blue-600" /> Work</span>
                <span className="flex items-center gap-1"><span className="h-2 w-2 rounded-full bg-gray-200" /> Weekend</span>
              </div>
            </div>

            <div className="grid grid-cols-7 gap-1">
              {['M', 'T', 'W', 'T', 'F', 'S', 'S'].map((d, i) => (
                <div key={i} className="pb-2 text-center text-xs font-bold text-gray-300">{d}</div>
              ))}
              
              {/* Jan 1 2026 is a Thursday. So we need 3 empty slots for Mon-Wed */}
              {[null, null, null].map((_, i) => <div key={`empty-${i}`} />)}

              {Array.from({ length: 31 }).map((_, i) => {
                const day = i + 1;
                const dateStr = `2026-01-${day < 10 ? `0${day}` : day}`;
                const dateObj = new Date(2026, 0, day); // Correct JS Date object
                const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
                
                const isSelected = selectedRange.start === dateStr || selectedRange.end === dateStr;
                const inRange = selectedRange.start && selectedRange.end && dateStr > selectedRange.start && dateStr < selectedRange.end;

                return (
                  <button
                    key={day}
                    onClick={() => handleDateClick(dateStr)}
                    className={`h-12 w-full rounded-xl text-sm font-bold transition-all flex flex-col items-center justify-center ${
                      isSelected ? "bg-blue-600 text-white shadow-lg" : 
                      inRange ? "bg-blue-50 text-blue-600" : 
                      isWeekend ? "text-gray-300 bg-gray-50" : "hover:bg-gray-100"
                    }`}
                  >
                    {day}
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        {/* RIGHT: Routing & Details */}
        <div className="lg:col-span-3 space-y-6 order-3">
          <div className={`rounded-2xl border border-gray-200 bg-white p-6 shadow-sm dark:border-gray-800 dark:bg-white/[0.03] ${!selectedRange.end ? 'opacity-40 grayscale pointer-events-none' : ''}`}>
            <h3 className="font-bold mb-4 text-sm">Absence Details</h3>
            <div className="space-y-4">
                <div className="space-y-1">
                    <label className="text-[10px] font-bold text-gray-400 uppercase">Absence Type</label>
                    <select className="w-full bg-transparent border-b border-gray-200 py-2 text-sm font-bold outline-none focus:border-blue-500">
                        <option>Annual Leave</option>
                        <option>Sick Leave</option>
                    </select>
                </div>

                <div className="space-y-1 pt-2">
                    <label className="text-[10px] font-bold text-gray-400 uppercase">Approval Route</label>
                    <div className="flex items-center gap-2 mt-1">
                        <div className="h-6 w-6 rounded-full bg-slate-200" />
                        <span className="text-xs font-bold text-gray-700">Sarah Jenkins (Manager)</span>
                    </div>
                </div>

                <div className="pt-4 border-t border-gray-50">
                    <div className="flex justify-between items-center text-xs mb-2">
                        <span className="text-gray-400">Net Business Days</span>
                        <span className="font-black text-slate-900">{analysis.working}</span>
                    </div>
                    <button className="w-full bg-blue-600 text-white py-3 rounded-xl font-bold text-xs flex items-center justify-center gap-2 hover:bg-blue-700">
                        Submit Request <ArrowRight className="h-4 w-4" />
                    </button>
                </div>
            </div>
          </div>
        </div>

      </div>
    </div>
  );
}

function BalanceRow({ label, current, requested, color }: { label: string, current: number, requested: number, color: string }) {
    const remains = current - requested;
    return (
        <div className="space-y-1">
            <div className="flex justify-between text-[11px] font-bold">
                <span className="text-gray-500">{label}</span>
                <span>{remains} / {current} Left</span>
            </div>
            <div className="h-1.5 w-full bg-gray-100 rounded-full overflow-hidden">
                <div className={`h-full ${color} transition-all duration-500`} style={{ width: `${(remains/current)*100}%` }} />
            </div>
        </div>
    );
}